-- ============================================
-- LUMA — Thème 9 (Donjon/JDR) : 3 scénarios COURTS x4
-- ============================================


update scenarios set content = '{"characters": {"gamemaster": "le maître du jeu"}, "start_node": "n1", "nodes": {"n1": {"speaker": "gamemaster", "text": "Welcome, adventurer! Before we begin, you must choose your class. What calls to you?", "text_fr": "Bienvenue, aventurier ! Avant de commencer, vous devez choisir votre classe. Qu''est-ce qui vous appelle ?", "choices": [{"text": "A warrior — strength and steel are my answer to any problem.", "text_fr": "Un guerrier — la force et l''acier sont ma réponse à tout problème.", "next": "n2"}, {"text": "A mage — I''d rather solve problems with knowledge and magic.", "text_fr": "Un mage — je préfère résoudre les problèmes avec le savoir et la magie.", "next": "n2b"}, {"text": "A rogue — cunning and stealth suit me better than brute force.", "text_fr": "Un voleur — la ruse et la discrétion me conviennent mieux que la force brute.", "next": "n2c"}]}, "n2": {"speaker": "gamemaster", "text": "A warrior! Bold and direct. Why does this path call to you?", "text_fr": "Un guerrier ! Audacieux et direct. Pourquoi cette voie vous appelle-t-elle ?", "choices": [{"text": "I believe true strength comes from protecting those who can''t protect themselves.", "text_fr": "Je crois que la vraie force vient du fait de protéger ceux qui ne peuvent pas se protéger eux-mêmes.", "next": "n3"}]}, "n2b": {"speaker": "gamemaster", "text": "A mage! The path of knowledge. What draws you to arcane study?", "text_fr": "Un mage ! La voie du savoir. Qu''est-ce qui vous attire vers l''étude arcanique ?", "choices": [{"text": "Magic offers solutions that brute force never could.", "text_fr": "La magie offre des solutions que la force brute ne pourrait jamais offrir.", "next": "n3"}]}, "n2c": {"speaker": "gamemaster", "text": "A rogue! Cunning over combat. What made you choose this path?", "text_fr": "Un voleur ! La ruse plutôt que le combat. Qu''est-ce qui vous a fait choisir cette voie ?", "choices": [{"text": "I''ve learned that the smartest solution is rarely the loudest one.", "text_fr": "J''ai appris que la solution la plus intelligente est rarement la plus bruyante.", "next": "n3"}]}, "n3": {"speaker": "gamemaster", "text": "A fine reason indeed. Now, what is your character''s name?", "text_fr": "Une belle raison en effet. Maintenant, quel est le nom de votre personnage ?", "choices": [{"text": "They call me Kael, wanderer of the northern roads.", "text_fr": "On m''appelle Kael, vagabond des routes du nord.", "next": "n4"}, {"text": "I go by Lyra, though few know my true name.", "text_fr": "On m''appelle Lyra, bien que peu connaissent mon vrai nom.", "next": "n4"}]}, "n4": {"speaker": "gamemaster", "text": "Excellent! Your journey begins now, in the town of Millhaven.", "text_fr": "Excellent ! Votre voyage commence maintenant, dans la ville de Millhaven.", "choices": [{"text": "I''m ready. Let the adventure begin!", "text_fr": "Je suis prêt. Que l''aventure commence !", "next": "end_created"}]}, "end_created": {"speaker": "gamemaster", "text": "Then let us begin, brave adventurer. Your story awaits.", "text_fr": "Alors commençons, brave aventurier. Votre histoire vous attend.", "end": true, "ending_label": "Personnage créé, l''aventure commence ⚔️🎭"}}}'::jsonb, is_playable = true
where title = 'Créer son personnage et choisir sa classe'
  and theme_id = (select id from scenario_themes where position = 9 and language_id = (select id from languages where code = 'en'));


update scenarios set content = '{"characters": {"gamemaster": "le maître du jeu"}, "start_node": "n1", "nodes": {"n1": {"speaker": "gamemaster", "text": "You notice the floor tiles ahead look slightly different — a pressure trap, perhaps.", "text_fr": "Vous remarquez que les dalles du sol devant semblent légèrement différentes — un piège à pression, peut-être.", "choices": [{"text": "Examine the tiles closely before stepping any further.", "text_fr": "Examine les dalles de près avant d''avancer davantage.", "next": "n2"}, {"text": "Try to find a way around the suspicious tiles.", "text_fr": "Essaie de trouver un moyen de contourner les dalles suspectes.", "next": "n2b"}]}, "n2": {"speaker": "gamemaster", "text": "Up close, you spot faint pressure plates beneath a thin layer of dust.", "text_fr": "De près, vous repérez de faibles plaques de pression sous une fine couche de poussière.", "choices": [{"text": "Try to disarm the mechanism carefully with your tools.", "text_fr": "Essaie de désamorcer le mécanisme prudemment avec tes outils.", "next": "n3"}, {"text": "Look for the trigger point to avoid it entirely.", "text_fr": "Cherche le point de déclenchement pour l''éviter entièrement.", "next": "n3b"}]}, "n2b": {"speaker": "gamemaster", "text": "The corridor is narrow — going around would mean climbing along the wall.", "text_fr": "Le couloir est étroit — contourner signifierait grimper le long du mur.", "choices": [{"text": "Attempt the wall climb carefully, avoiding the tiles below.", "text_fr": "Tente l''escalade du mur prudemment, en évitant les dalles en dessous.", "next": "n3c"}]}, "n3": {"speaker": "gamemaster", "text": "(Rolling for skill) Your steady hands work at the mechanism, click by click.", "text_fr": "(Jet de compétence) Vos mains stables travaillent sur le mécanisme, clic par clic.", "choices": [{"text": "Continue working, staying calm and precise.", "text_fr": "Continue à travailler, en restant calme et précis.", "next": "n4"}]}, "n3b": {"speaker": "gamemaster", "text": "You spot a single loose tile near the wall — the safe path.", "text_fr": "Vous repérez une seule dalle desserrée près du mur — le chemin sûr.", "choices": [{"text": "Step carefully along the wall, avoiding the trapped tiles.", "text_fr": "Avance prudemment le long du mur, en évitant les dalles piégées.", "next": "n4"}]}, "n3c": {"speaker": "gamemaster", "text": "(Rolling for athletics) Your fingers find grip on the ancient stonework.", "text_fr": "(Jet d''athlétisme) Vos doigts trouvent prise sur la maçonnerie ancienne.", "choices": [{"text": "Keep climbing steadily toward the other side.", "text_fr": "Continue à grimper régulièrement vers l''autre côté.", "next": "n4"}]}, "n4": {"speaker": "gamemaster", "text": "(Success!) With a soft click, the trap mechanism deactivates completely.", "text_fr": "(Succès !) Avec un léger clic, le mécanisme du piège se désactive complètement.", "choices": [{"text": "Proceed forward, relieved the trap is disarmed.", "text_fr": "Avance, soulagé que le piège soit désamorcé.", "next": "end_disarmed"}]}, "end_disarmed": {"speaker": "gamemaster", "text": "The path ahead is now clear. Your skill has served you well, adventurer.", "text_fr": "Le chemin devant est maintenant dégagé. Votre compétence vous a bien servi, aventurier.", "end": true, "ending_label": "Piège désamorcé avec succès 🪤✅"}}}'::jsonb, is_playable = true
where title = 'Un premier piège à désamorcer'
  and theme_id = (select id from scenario_themes where position = 9 and language_id = (select id from languages where code = 'en'));
